def f(n):
    if n == 0:
        return 0
    # Extracting odd part
    return n >> (n & -n).bit_length() - 1

def s(n):
    return f(n) % 4

def check_v(v, u_max=100000):
    # Precompute s_n for a large range
    # Max n we need is u_max + 2*v
    seq = [s(n) for n in range(u_max + 2 * v + 1)]
    for u in range(1, u_max + 1):
        possible = True
        for k in range(v):
            if seq[u + k] != seq[u + v + k]:
                possible = False
                break
        if possible:
            return True, u
    return False, None

for v in range(1, 16):
