def s(n):
    if n == 0: return 0
    return (n >> (n & -n).bit_length() - 1) % 4

def check_v_fast(v, u_max=1000000):
    seq = [s(n) for n in range(1, u_max + 2 * v + 1)]
    for u in range(u_max):
        if seq[u : u + v] == seq[u + v : u + 2 * v]:
            return True, u + 1
    return False, None

for v in range(1, 21):
